package io.invenlio.procurement;
import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.testcontainers.service.connection.ServiceConnection;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.*;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers@SpringBootTest@AutoConfigureMockMvc@ActiveProfiles("test")class PurchaseOrderIntegrationTest{static final UUID T=UUID.fromString("91111111-1111-4111-8111-111111111111"),S=UUID.randomUUID(),W=UUID.randomUUID(),V=UUID.randomUUID(),SP=UUID.randomUUID();@Container@ServiceConnection static final PostgreSQLContainer DB=new PostgreSQLContainer("postgres:17.6-alpine");@Autowired JdbcTemplate db;@Autowired MockMvc mvc;
 @BeforeEach void seed(){db.update("INSERT INTO organizations(id,name,slug,status,default_locale,default_timezone,default_currency,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','en','UTC','EUR',now(),now(),0)",T,"PO Tenant","po-tenant");UUID u=UUID.randomUUID(),m=UUID.randomUUID(),r=UUID.randomUUID(),p=UUID.randomUUID();db.update("INSERT INTO user_identities(id,keycloak_subject,status,created_at,updated_at)VALUES(?,?,'ACTIVE',now(),now())",u,"buyer");db.update("INSERT INTO organization_memberships(id,tenant_id,user_identity_id,status,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE',now(),now(),0)",m,T,u);db.update("INSERT INTO roles(id,tenant_id,name,system_role,created_at,updated_at,version)VALUES(?,?,?,false,now(),now(),0)",r,T,"PO TEST");for(String x:List.of("purchase-order:read","purchase-order:create","purchase-order:update","purchase-order:approve","purchase-order:cancel"))db.update("INSERT INTO role_permissions VALUES(?,?,?)",T,r,x);db.update("INSERT INTO membership_roles VALUES(?,?,?)",T,m,r);db.update("INSERT INTO suppliers(id,tenant_id,supplier_number,normalized_supplier_number,name,legal_name,status,default_currency,payment_terms_days,default_lead_time_days,created_at,updated_at,version)VALUES(?,?, 'SUP-1','SUP-1','Original Supplier','Original Legal','ACTIVE','EUR',30,7,now(),now(),0)",S,T);db.update("INSERT INTO warehouses(id,tenant_id,code,normalized_code,name,status,timezone,created_at,updated_at,version)VALUES(?,?, 'WH-1','WH-1','Main Warehouse','ACTIVE','UTC',now(),now(),0)",W,T);db.update("INSERT INTO catalog_products(id,tenant_id,name,status,base_unit,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','EA',now(),now(),0)",p,T,"Widget");db.update("INSERT INTO catalog_product_variants(id,tenant_id,product_id,sku,normalized_sku,status,display_name,base_unit,option_signature,created_at,updated_at,version)VALUES(?,?,?,?,?,'ACTIVE','Widget Blue','EA','DEFAULT',now(),now(),0)",V,T,p,"SKU-1","SKU-1");db.update("INSERT INTO supplier_products(id,tenant_id,supplier_id,variant_id,supplier_sku,normalized_supplier_sku,purchase_unit_code,base_units_per_purchase_unit,minimum_order_quantity,order_multiple,unit_cost,currency,lead_time_days,active,preferred,created_at,updated_at,version)VALUES(?,?,?,?,?,?,'BOX',20,5,2.5,12.345600,'EUR',7,true,false,now(),now(),0)",SP,T,S,V,"EXT-1","EXT-1");}
 @AfterEach void clean(){db.execute("TRUNCATE purchase_order_lines,purchase_orders,purchase_order_number_counters CASCADE");db.update("DELETE FROM supplier_products WHERE tenant_id=?",T);db.update("DELETE FROM catalog_product_variants WHERE tenant_id=?",T);db.update("DELETE FROM catalog_products WHERE tenant_id=?",T);db.update("DELETE FROM warehouses WHERE tenant_id=?",T);db.update("DELETE FROM suppliers WHERE tenant_id=?",T);db.update("DELETE FROM audit_events WHERE tenant_id=?",T);db.update("DELETE FROM membership_roles WHERE tenant_id=?",T);db.update("DELETE FROM role_permissions WHERE tenant_id=?",T);db.update("DELETE FROM organization_memberships WHERE tenant_id=?",T);db.update("DELETE FROM roles WHERE tenant_id=?",T);db.update("DELETE FROM user_identities WHERE keycloak_subject='buyer'");db.update("DELETE FROM organizations WHERE id=?",T);}
 @Test void workflowUsesExactSnapshotsAndNeverMutatesInventory()throws Exception{int movements=count("inventory_movements"),ledger=count("inventory_ledger_entries"),balances=count("inventory_balances"),reservations=count("inventory_reservations");UUID po=create();mvc.perform(post("/api/v1/purchase-orders/"+po+"/lines").with(token()).contentType("application/json").content("{\"supplierProductId\":\""+SP+"\",\"orderedQuantity\":\"7.5\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.baseQuantity").value(150.0)).andExpect(jsonPath("$.lineSubtotal").value(92.592)).andExpect(jsonPath("$.supplierSku").value("EXT-1"));db.update("UPDATE suppliers SET name='Changed Supplier' WHERE id=?",S);db.update("UPDATE supplier_products SET unit_cost=99,supplier_sku='NEW',normalized_supplier_sku='NEW' WHERE id=?",SP);mvc.perform(get("/api/v1/purchase-orders/"+po).with(token())).andExpect(jsonPath("$.supplierName").value("Original Supplier")).andExpect(jsonPath("$.lines[0].unitCost").value(12.3456)).andExpect(jsonPath("$.lines[0].supplierSku").value("EXT-1"));mvc.perform(post("/api/v1/purchase-orders/"+po+"/submit").with(token()).contentType("application/json").content("{\"version\":1}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("SUBMITTED"));mvc.perform(post("/api/v1/purchase-orders/"+po+"/approve").with(token()).contentType("application/json").content("{\"version\":2}")).andExpect(status().isOk());mvc.perform(post("/api/v1/purchase-orders/"+po+"/mark-sent").with(token()).contentType("application/json").content("{\"version\":3}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("SENT"));assertEquals(movements,count("inventory_movements"));assertEquals(ledger,count("inventory_ledger_entries"));assertEquals(balances,count("inventory_balances"));assertEquals(reservations,count("inventory_reservations"));}
 @Test void emptyMoqMultipleDuplicateAndIssuedMutationRulesHold()throws Exception{UUID po=create();mvc.perform(post("/api/v1/purchase-orders/"+po+"/submit").with(token()).contentType("application/json").content("{\"version\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("PURCHASE_ORDER_EMPTY"));add(po,"3").andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("MINIMUM_ORDER_QUANTITY_NOT_MET"));add(po,"7").andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("ORDER_MULTIPLE_VIOLATION"));String line=add(po,"7.5").andExpect(status().isOk()).andReturn().getResponse().getContentAsString();UUID lineId=id(line);add(po,"10").andExpect(status().isBadRequest());mvc.perform(post("/api/v1/purchase-orders/"+po+"/submit").with(token()).contentType("application/json").content("{\"version\":1}")).andExpect(status().isOk());mvc.perform(patch("/api/v1/purchase-orders/"+po+"/lines/"+lineId).with(token()).contentType("application/json").content("{\"orderedQuantity\":\"10\",\"version\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("PURCHASE_ORDER_NOT_EDITABLE"));}
 @Test void concurrentNumbersAreUnique()throws Exception{ExecutorService pool=Executors.newFixedThreadPool(12);try{List<Future<String>>calls=new ArrayList<>();for(int i=0;i<20;i++)calls.add(pool.submit(()->mvc.perform(post("/api/v1/purchase-orders").with(token()).contentType("application/json").content(createJson())).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()));Set<String>numbers=new HashSet<>();for(var f:calls)numbers.add(f.get().replaceAll(".*\"number\":\"([^\"]+)\".*","$1"));assertEquals(20,numbers.size());assertEquals(20,db.queryForObject("SELECT count(*) FROM purchase_orders",Integer.class));}finally{pool.shutdownNow();}}
 @Test void concurrentApprovalHasOneWinner()throws Exception{UUID po=ready();Set<Integer>s=race(()->postStatus(po,"approve",2,null),()->postStatus(po,"approve",2,null));assertEquals(Set.of(200,409),s);assertEquals("APPROVED",db.queryForObject("SELECT status FROM purchase_orders WHERE id=?",String.class,po));assertEquals(1,db.queryForObject("SELECT count(*) FROM audit_events WHERE tenant_id=? AND action='PURCHASE_ORDER_APPROVED'",Integer.class,T));}
 @Test void approveCancelRaceAndEditSubmitRaceStayConsistent()throws Exception{UUID po=ready();Set<Integer>s=race(()->postStatus(po,"approve",2,null),()->postStatus(po,"cancel",2,"Commercial stop"));assertEquals(Set.of(200,409),s);assertTrue(Set.of("APPROVED","CANCELLED").contains(db.queryForObject("SELECT status FROM purchase_orders WHERE id=?",String.class,po)));UUID draft=create();UUID line=id(add(draft,"7.5").andExpect(status().isOk()).andReturn().getResponse().getContentAsString());race(()->mvc.perform(patch("/api/v1/purchase-orders/"+draft+"/lines/"+line).with(token()).contentType("application/json").content("{\"orderedQuantity\":\"10\",\"version\":0}")).andReturn().getResponse().getStatus(),()->postStatus(draft,"submit",1,null));String state=db.queryForObject("SELECT status FROM purchase_orders WHERE id=?",String.class,draft);if(state.equals("SUBMITTED"))assertEquals(0,db.queryForObject("SELECT count(*) FROM purchase_order_lines WHERE id=? AND ordered_quantity=10",Integer.class,line));}
 @Test void securityTenantAndApprovalPermissionAreEnforced()throws Exception{mvc.perform(get("/api/v1/purchase-orders")).andExpect(status().isUnauthorized());UUID po=create();UUID other=UUID.randomUUID();mvc.perform(get("/api/v1/purchase-orders/"+po).with(jwt().jwt(j->j.subject("buyer").claim("tenant_id",other.toString())))).andExpect(status().isForbidden());db.update("DELETE FROM role_permissions WHERE tenant_id=? AND permission_key='purchase-order:approve'",T);add(po,"7.5");mvc.perform(post("/api/v1/purchase-orders/"+po+"/submit").with(token()).contentType("application/json").content("{\"version\":1}")).andExpect(status().isOk());mvc.perform(post("/api/v1/purchase-orders/"+po+"/approve").with(token()).contentType("application/json").content("{\"version\":2}")).andExpect(status().isForbidden());}
 private UUID ready()throws Exception{UUID po=create();add(po,"7.5").andExpect(status().isOk());postStatus(po,"submit",1,null);return po;}private UUID create()throws Exception{return id(mvc.perform(post("/api/v1/purchase-orders").with(token()).contentType("application/json").content(createJson())).andExpect(status().isOk()).andExpect(jsonPath("$.number").value(org.hamcrest.Matchers.matchesPattern("PO-[0-9]{4}-[0-9]{6}"))).andReturn().getResponse().getContentAsString());}private ResultActions add(UUID po,String q)throws Exception{return mvc.perform(post("/api/v1/purchase-orders/"+po+"/lines").with(token()).contentType("application/json").content("{\"supplierProductId\":\""+SP+"\",\"orderedQuantity\":\""+q+"\"}"));}private int postStatus(UUID po,String action,long v,String reason)throws Exception{String body=reason==null?"{\"version\":"+v+"}":"{\"version\":"+v+",\"reason\":\""+reason+"\"}";return mvc.perform(post("/api/v1/purchase-orders/"+po+"/"+action).with(token()).contentType("application/json").content(body)).andReturn().getResponse().getStatus();}private Set<Integer>race(Callable<Integer>a,Callable<Integer>b)throws Exception{ExecutorService p=Executors.newFixedThreadPool(2);try{CountDownLatch go=new CountDownLatch(1);Future<Integer>x=p.submit(()->{go.await();return a.call();}),y=p.submit(()->{go.await();return b.call();});go.countDown();return Set.of(x.get(),y.get());}finally{p.shutdownNow();}}private int count(String table){return db.queryForObject("SELECT count(*) FROM "+table,Integer.class);}private String createJson(){return "{\"supplierId\":\""+S+"\",\"warehouseId\":\""+W+"\",\"supplierReference\":\"QUOTE-1\"}";}private UUID id(String json){return UUID.fromString(json.replaceAll(".*\"id\":\"([^\"]+)\".*","$1"));}private org.springframework.test.web.servlet.request.RequestPostProcessor token(){return jwt().jwt(j->j.subject("buyer").claim("tenant_id",T.toString()));}}
